Q: pnpm reports incorrect peer dependency version warning when `vite` is aliased to `@voidzero-dev/vite-plus-core` by Vite+ A: <p>Until a proper solution is available, pnpm can still be manipulated in an automated way.</p>
<h3>Solution via Script</h3>
<p>Just create <code>.pnpmfile.cjs</code> and override <code>@voidzero-dev/vite-plus-core</code> version dynamically with <code>bundledVersions.vite</code>.</p>
<p>This makes it possible to retrieve the actual Vite version from <code>bundledVersions.vite</code>, and then use it to add VitePlus support only to packages that truly support that specific version. So if <code>bundledVersions.vite</code> is v8, but you install a dependency that only supports Vite 5-7, you will still receive the warning.</p>
<p><strong>.pnpmfile.cjs</strong> (in your project root)</p>
<pre class="lang-js prettyprint-override"><code>let vitePlusCoreVersion = null;
let bundledVite = null;
const logs = [];

// pnpm alias resolves vite instead of @voidzero-dev/vite-plus-core, try both paths
const candidates = [
  &quot;./node_modules/vite/package.json&quot;,
  &quot;./node_modules/@voidzero-dev/vite-plus-core/package.json&quot;,
];

for (const candidate of candidates) {
  try {
    const viteCore = require(candidate);
    if (viteCore.name === &quot;@voidzero-dev/vite-plus-core&quot;) {
      vitePlusCoreVersion = viteCore.version;
      bundledVite = viteCore.bundledVersions?.vite;
      logs.push(`Loaded from ${candidate}: ${vitePlusCoreVersion} (bundled vite: ${bundledVite})`);
      break;
    }
  } catch {}
}

if (!bundledVite) {
  logs.push(&quot;vite-plus-core not found, peer dependency ranges will not be extended&quot;);
}

function satisfiesRange(version, range) {
  const bundledMajor = parseInt(version.split(&quot;.&quot;)[0], 10);
  const majorsInRange = [...range.matchAll(/\^?(\d+)/g)].map(m =&gt; parseInt(m[1], 10));
  return majorsInRange.includes(bundledMajor);
}

function extendViteRange(pkg, field) {
  const deps = pkg[field];
  if (!deps?.vite || !bundledVite || !vitePlusCoreVersion) return;

  if (satisfiesRange(bundledVite, deps.vite)) {
    logs.push(`${pkg.name}[${field}]: ${deps.vite} || ${vitePlusCoreVersion}`);
    deps.vite = `${deps.vite} || ${vitePlusCoreVersion}`;
  }
  // If the range does not match, the package does not support the vite version specified
  // in bundledVersions - this is more precise than blindly allowing all vite-plus-core
  // versions via ^0 or adding them manually one by one.
}

function readPackage(pkg) {
  extendViteRange(pkg, &quot;dependencies&quot;);
  extendViteRange(pkg, &quot;devDependencies&quot;);
  extendViteRange(pkg, &quot;peerDependencies&quot;);
  return pkg;
}

function afterAllResolved(lockfile) {
  if (logs.length) {
    console.log(&quot;\n[Fix Vite version]\n&quot; + logs.join(&quot;\n&quot;) + &quot;\n\n&quot;);
  }
  return lockfile;
}

module.exports = { hooks: { readPackage, afterAllResolved } };
</code></pre>
